t.script:
(function () {
  "use strict";
  function $(s,r){return (r||document).querySelector(s);}
  function $val(id,d){var el=$("#"+id);return el?el.value:d;}
  function loadImage(src){return new Promise(function(res,rej){var i=new Image();i.onload=function(){res(i);};i.onerror=rej;i.src=src;});}
  function readAsDataURL(f){return new Promise(function(res,rej){var r=new FileReader();r.onload=function(){res(r.result);};r.onerror=rej;r.readAsDataURL(f);});}

  function applyTransform(){
    var logo=$("#spw_logo_preview"), base=$("#spw_product_img");
    if(!logo||!base) return;
    var size=+($val("spw_size","100")), x=+($val("spw_pos_x","0")), y=+($val("spw_pos_y","10")), rot=+($val("spw_rotation","0"));
    var bw=base.clientWidth, bh=base.clientHeight;
    var left=bw*(0.5+x/100), top=bh*(0.6+y/100);
    Object.assign(logo.style,{
      position:"absolute",left:left+"px",top:top+"px",
      transform:"translate(-50%,-50%) rotate("+rot+"deg)",width:size+"px",opacity:"1"
    });
    logo.classList.remove("d-none");
  }

  async function renderPNGDataURL(){
    var internal=$("#spw-base-img"),
        baseSrc=(internal&&internal.getAttribute("src"))||$val("spw_img_src","")||($("#spw_product_img")||{}).getAttribute("src");
    if(!baseSrc) throw new Error("Sin base");
    var base=await loadImage(baseSrc);
    var c=document.createElement("canvas"),ctx=c.getContext("2d");
    c.width=base.naturalWidth||base.width; c.height=base.naturalHeight||base.height;
    ctx.drawImage(base,0,0,c.width,c.height);

    var logo=$("#spw_logo_preview");
    if(logo&&logo.src){
      var be=$("#spw_product_img"), bw=be.clientWidth, bh=be.clientHeight,
          br=be.getBoundingClientRect(), lr=logo.getBoundingClientRect();
      var cx=((lr.left+lr.width/2)-br.left)/bw*c.width, cy=((lr.top+lr.height/2)-br.top)/bh*c.height;
      var drawW=(lr.width/bw)*c.width, img=await loadImage(logo.src),
          ratio=(img.naturalHeight||img.height)/(img.naturalWidth||img.width),
          drawH=drawW*ratio, rot=(+$val("spw_rotation","0")*Math.PI)/180;
      ctx.save(); ctx.translate(cx,cy); ctx.rotate(rot);
      ctx.drawImage(img,-drawW/2,-drawH/2,drawW,drawH); ctx.restore();
    }
    return c.toDataURL("image/png");
  }

  async function postJSON(url,payload){
    try{
      var r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","X-Requested-With":"XMLHttpRequest"},credentials:"same-origin",body:JSON.stringify(payload)});
      var t=await r.text(); var d=null; try{d=JSON.parse(t);}catch(_){}
      return {ok:!!(d&&(d.ok===true||d.ok==="true")),data:d,status:r.status,raw:t};
    }catch(e){return {ok:false,data:null,status:0,raw:String(e)};}
  }
  async function postForm(url,payload){
    try{
      var fd=new FormData(); Object.keys(payload||{}).forEach(k=>fd.append(k,payload[k]));
      var r=await fetch(url,{method:"POST",body:fd,credentials:"same-origin"});
      var t=await r.text(); var d=null; try{d=JSON.parse(t);}catch(_){}
      return {ok:r.ok&&(!!d?(d.ok===true||d.ok==="true"):true),data:d||{},status:r.status,raw:t};
    }catch(e){return {ok:false,data:null,status:0,raw:String(e)};}
  }

  async function addToCart(){
    var vid=($val("spw_variant_id","")||"").trim(); if(!vid){alert("Falta la variante");return;}
    var qty=+( $val("spw_qty","1") )||1;
    var tech=(document.querySelector("input[name='spw_tech']:checked")||{}).value||"";
    var color=(document.querySelector("input[name='spw_svg_color']:checked")||{}).value||"";
    var notes=($val("spw_notes","")||"").trim();

    var pngB64=""; try{
      var du=await renderPNGDataURL();
      sessionStorage.setItem('spw_last_product_id', String(vid));
      sessionStorage.setItem('spw_last_png', du||'');
      sessionStorage.setItem('spw_last_color', color||'');
      pngB64 = du ? du.split('base64,')[1] : "";
    }catch(_){}

    var r1=await postJSON("/spw/add_to_cart_meta",{variant_id:+vid,qty:qty,tech:tech,svg_color:color,notes:notes});
    if(!r1.ok){ r1=await postForm("/spw/add_to_cart_meta_http",{variant_id:vid,qty:qty,tech:tech,svg_color:color,notes:notes}); }
    if(!r1.ok){ alert((r1.data&&r1.data.message)?r1.data.message:"No se pudo añadir al carrito."); return; }

    try{ if(r1.data && r1.data.line_id) sessionStorage.setItem('spw_last_line_id', String(r1.data.line_id)); }catch(_){}
    if(pngB64){
      var r2=await postJSON("/spw/attach_png",{line_id:r1.data.line_id,png_b64:pngB64});
      if(!r2.ok){ await postForm("/spw/attach_png_http",{line_id:r1.data.line_id,png_b64:pngB64}); }
    }

    var base=(r1.data&&r1.data.cart_url)||"/shop/cart";
    var url=(r1.data&&r1.data.line_id)?(base+(base.indexOf('?')===-1?'?':'&')+'spw_line_id='+encodeURIComponent(r1.data.line_id)):base;
    window.location.href=url;
  }

  async function downloadPNGiOSSafe(){
    try{
      var dataUrl=await renderPNGDataURL();
      var a=document.createElement("a"); a.href=dataUrl; a.download="personalizacion.png";
      if(typeof a.download==="undefined"){ window.location.href=dataUrl; } else { document.body.appendChild(a); a.click(); a.remove(); }
    }catch(_){ alert("No se pudo generar el PNG."); }
  }

  function init(){
    var inLogo=document.getElementById("spw_logo_input"), logo=document.getElementById("spw_logo_preview");
    if(inLogo){ inLogo.addEventListener("change", async function(ev){ var f=ev.target.files&&ev.target.files[0]; if(!f)return; var du=await readAsDataURL(f); logo.src=du; applyTransform(); }); }
    ["spw_size","spw_pos_x","spw_pos_y","spw_rotation"].forEach(function(id){ var el=document.getElementById(id); if(el) el.addEventListener("input",applyTransform); });
    window.spwReset=function(){ document.getElementById("spw_size").value=100; document.getElementById("spw_pos_x").value=0; document.getElementById("spw_pos_y").value=10; document.getElementById("spw_rotation").value=0; applyTransform(); };
    var dl=document.getElementById("spw_download_png"); if(dl) dl.addEventListener("click", downloadPNGiOSSafe);
    var add=document.getElementById("spw_add_to_cart"); if(add) add.addEventListener("click", addToCart);
    applyTransform();
  }
  if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init);}else{init();}
})();
